INSERT INTO cms.pages(slug,title,summary,body,published) VALUES ('iletisim','NEXUS ile iletişime geçin','Satış, iş ortaklığı ve teknik destek talepleriniz için bize ulaşın.','E-posta: hello@nexustraveltech.com\n\nİş ortaklığı ve tedarikçi başvuruları için çalışma alanından başvurun.\nTeknik destek: support@nexustraveltech.com',jsonb_build_object('title','NEXUS ile iletişime geçin','summary','Satış, iş ortaklığı ve teknik destek talepleriniz için bize ulaşın.','body','E-posta: hello@nexustraveltech.com\n\nİş ortaklığı ve tedarikçi başvuruları için çalışma alanından başvurun.\nTeknik destek: support@nexustraveltech.com')) ON CONFLICT(slug) DO NOTHING;
CREATE FUNCTION cms.delete_page(p_slug text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN IF NOT cms.can_edit() OR NOT EXISTS(SELECT FROM auth.users WHERE id=nullif(current_setting('app.actor_id',true),'')::uuid AND role='owner') THEN RETURN 'forbidden'; END IF; IF p_slug IN ('home','program','tedarikci','acente','hakkimizda','iletisim') THEN RETURN 'protected'; END IF; DELETE FROM cms.pages WHERE slug=p_slug; RETURN CASE WHEN FOUND THEN 'deleted' ELSE 'not_found' END; END $$;
GRANT EXECUTE ON FUNCTION cms.delete_page(text) TO nexus_app;
